column = 'Population'
operation = 'type_change'
other_column = None
start = None
end = None
find = None
replace_with = None
new_column = None
separator = ' '
replace_type = 'float'
if df is None:
    raise ValueError("A DataFrame must be provided.")
if column not in df.columns:
    raise ValueError(f"Column {column} not found in DataFrame.")

new_col = new_column or column

try:
    if operation == 'lowercase':
        df[new_col] = df[column].astype(str).str.lower()
    elif operation == 'uppercase':
        df[new_col] = df[column].astype(str).str.upper()
    elif operation == 'titlecase':
        df[new_col] = df[column].astype(str).str.title()
    elif operation == 'substring':
        if start is None:
            raise ValueError('start must be specified for substring.')
        df[new_col] = df[column].astype(str).str[start:end]
    elif operation == "concat":
        if other_column is None:
            raise ValueError("`other_column` must be specified for concatenation.")
        if other_column not in df.columns:
            raise ValueError(f"other_column not found in DataFrame.")
        df[new_col] = df[column].astype(str) + separator + df[other_column].astype(str)
    elif operation == "replace":
        if find is None:
            raise ValueError("`find` must be specified for replace.")
        replacement_value = pd.NA if replace_with == 'pd.NA' else replace_with
        df[new_col] = df[column].replace(find, replacement_value, regex=True)



    elif operation == "type_change":
        from typing import Literal, Dict, Optional, List, Union
        def safe_convert_dtype(series: pd.Series, dtype: Union[str, type], sample: int = 10) -> pd.Series:
            bad_rows = []
            results = []

            for idx, val in series.items():
                try:
                    if pd.isna(val):
                        results.append(pd.NA)
                    elif str(dtype).startswith("datetime"):
                        results.append(pd.to_datetime(val))
                    else:
                        results.append(pd.Series([val]).astype(dtype).iloc[0])
                except Exception as e:
                    bad_rows.append((idx, val, str(e)))
                    results.append(pd.NA)

            if bad_rows:
                bad_vals = pd.Series([v for _, v, _ in bad_rows], dtype="object")
                vc = bad_vals.value_counts(dropna=False).head(sample)
                idx_preview = [i for i, _, _ in bad_rows[:sample]]
                err_preview = " ".join(f"Row {i}: {repr(v)}" for i, v, _ in bad_rows[:sample])

                raise ValueError(
                    f"Failed converting Series '{series.name}' to dtype {dtype!r} due to {len(bad_rows)} failed cases, such as \n"
                    f"{err_preview}"
                )

            return pd.Series(results, index=series.index, name=series.name)

        df[new_col] = safe_convert_dtype(df[column],replace_type)

    else:
        raise ValueError(f"Unsupported operation: {operation}")


except Exception as e:
    raise ValueError('error')

